/**
 * Symbol path registry for `ProhibitorySign`. Each entry is a list of black
 * glyph paths (extracted from the matching reference sign artwork) drawn on
 * top of the sign's background circle, using the same coordinate space as
 * `prohibitorySignShape.ts` (i.e. `PROHIBITORY_SIGN_VIEW_BOX` +
 * `PROHIBITORY_SIGN_GROUP_TRANSFORM`).
 *
 * Path data is extracted as-is from the reference artwork on Wikimedia
 * Commons (`Iceland_road_sign_<code>.svg`), only stripping fill colours
 * (supplied via the `ProhibitorySign` component's `symbolColour` prop
 * instead) and, where the source file used a different `<g transform>` than
 * `PROHIBITORY_SIGN_GROUP_TRANSFORM`, translating every point so coordinates
 * line up with the shared circle shape.
 *
 * Most symbols are a single colour and use plain `d` strings, recoloured via
 * `symbolColour` (same convention as `WarningSign`'s `warningSignSymbolPaths`).
 * A symbol part that must always render in a fixed colour regardless of
 * `symbolColour` can instead use the `{ d, colour }` form.
 *
 * Two multi-colour hazmat symbols in the reference artwork (`DangerousGoods`,
 * `WaterPollutingSubstances`) also had small orange/blue accent details in
 * addition to their black outline; those accents are dropped here and the
 * whole symbol renders as a single colour via `symbolColour`, same as every
 * other symbol.
 *
 * A few symbols (`LengthLimit`, `TotalWeightLimitCombination`,
 * `AxleWeightLimit`, `MinimumSpaceBetweenVehicles`) combine a pictogram with
 * free text rendered via `firstLineText` / `secondLineText` — the reference
 * artwork's baked-in digits/units are stripped out here in favour of those
 * props, and `ProhibitorySign.tsx` positions the text around the pictogram
 * for each of those symbols specifically.
 *
 * Not every prohibitory sign has a pictogram — purely text-based signs
 * (single-vehicle weight limits, speed limits, "stop for checkpoint", etc.)
 * are represented by the component's `firstLineText` / `secondLineText` props
 * instead and have no entry here.
 *
 * Add one entry per additional prohibitory sign symbol as new reference
 * artwork is stripped down.
 */
import type { RoadSignColour } from "../WarningSign/roadSignColors";

export type ProhibitorySignSymbol =
  | "Car"
  | "Truck"
  | "Bus"
  | "Tractor"
  | "Motorbike"
  | "Snowmobile"
  | "Moped"
  | "AllMotorVehicles"
  | "Bike"
  | "Equestrian"
  | "Pedestrian"
  | "DangerousGoods"
  | "WaterPollutingSubstances"
  | "TurnRightProhibited"
  | "TurnLeftProhibited"
  | "UTurnProhibited"
  | "OvertakingProhibited"
  | "OvertakingByTrucksProhibited"
  | "YieldToOncomingTraffic"
  | "MinimumSpaceBetweenVehicles"
  | "EntryProhibitedBar"
  | "WidthLimit"
  | "HeightLimit"
  | "LengthLimit"
  | "TotalWeightLimitCombination"
  | "AxleWeightLimit";

/**
 * A single symbol glyph path, either a plain `d` string (recoloured via the
 * component's `symbolColour` prop) or a `{ d, colour }` pair that always
 * renders in `colour` regardless of `symbolColour` — same convention as
 * `WarningSignSymbolPath` in `warningSignSymbols.ts`.
 */
export type ProhibitorySignSymbolPath = string | Readonly<{ d: string; colour: RoadSignColour }>;

